#include <vector>

class Solution {
public:
    std::vector<int> findCoins(std::vector<int>& dp) {
        int m = dp.size() - 1;
        if (m < 1 || dp[0] != 1) return {};

        std::vector<int> current(m + 1, 0);
        current[0] = 1;
        std::vector<int> coins;

        for (int i = 1; i <= m; ++i) {
            if (dp[i] > current[i]) {
                coins.push_back(i);
                for (int s = i; s <= m; ++s) {
                    current[s] += current[s - i];
                }
            }
        }

        return coins;
    }
};

import java.util.*;

class Solution {
    public int[] findCoins(int[] dp) {
        int m = dp.length - 1;
        if (m < 1 || dp[0] != 1) return new int[0];

        int[] current = new int[m + 1];
        current[0] = 1;
        List<Integer> coins = new ArrayList<>();

        for (int i = 1; i <= m; i++) {
            if (dp[i] > current[i]) {
                coins.add(i);
                for (int s = i; s <= m; s++) {
                    current[s] += current[s - i];
                }
            }
        }

        int[] res = new int[coins.size()];
        for (int i = 0; i < coins.size(); i++) res[i] = coins.get(i);
        return res;
    }
}

