var findCoins = function(dp) {
    const m = dp.length - 1;
    if (m < 1 || dp[0] !== 1) return [];

    const current = new Int32Array(m + 1);
    current[0] = 1;
    const coins = [];

    for (let i = 1; i <= m; i++) {
        if (dp[i] > current[i]) {
            coins.push(i);
            for (let s = i; s <= m; s++) {
                current[s] += current[s - i];
            }
        }
    }

